  [102011] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "对话",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    EventOptions = {
      "3|行过一生的人|也许，日出日落另有所指。",
      "3|孟斐斯的战象|这种动物的腿的确很多。",
      "3|雅弗的雄鹰|飞的时候腿会变化？",
      ""
    },
    EventResult = {
      "3|行过一生的人|雅弗士兵说：“啊，听您这么一说我茅塞顿开了，请您接受我的敬意。”",
      "3|孟斐斯的战象|答案应该不是这个，重新听一遍题目再思考一下吧。",
      "3|雅弗的雄鹰|答案应该不是这个，重新听一遍题目再思考一下吧。",
      ""
    },
    EventTitleText = "4|雅弗士兵|我被一些问题困扰已久，听闻楔文会的学者们都富有学识，我想请您替我答疑解惑。我的第一个问题是：不论是我等的故土雅弗，亦或是脚下的欧贝德，昼夜更迭都是无法可逆转的规律。那么，是否有那么一种生物，能在日出之时四腿齐行，日升之时双腿并进，却又在日落转为三腿行进？",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 102011,
    InteractRange = 3,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 1,
    IsRemove = 0,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "第二章特殊交互宝箱-反复交互罗马人1",
    PlayInteractSoundName = "",
    ServerEventPath = "box.102011",
    Shadow = 0,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
  [102012] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "对话",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    EventOptions = {
      "3|传说中的无足鸟|至少它们无法走路。",
      "3|奔流的提比利斯河|唯有河符合这谜题的所有条件。",
      "3|艺术馆中的肖像画|他们有口却从不说话，有头却从不流泪。",
      ""
    },
    EventResult = {
      "3|传说中的无足鸟|答案应该不是这个，重新听一遍题目再思考一下吧。",
      "3|奔流的提比利斯河|雅弗士兵说：“果然这道题难不住您啊，这是智者应得的尊重。”",
      "3|艺术馆中的肖像画|答案应该不是这个，重新听一遍题目再思考一下吧。",
      ""
    },
    EventTitleText = "4|雅弗士兵|请稍等，我尚有一些疑问未能得到解答，我曾听德尔菲的诗人吟唱一种神奇的存在，它们可以飞奔却从不走路，有口却从不说话，有头却从不流泪，有床却从不睡觉，世间果真存在这般事物么？",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 102012,
    InteractRange = 3,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 1,
    IsRemove = 0,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "第二章特殊交互宝箱-反复交互罗马人2",
