    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "对话",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    EventOptions = {
      "3|光辉的夜明珠|只在夜间闪耀的宝物？",
      "3|永恒的月亮|无人能够夺取天上的明月。",
      "3|璀璨的繁星|夜晚闪耀天幕的众多无价之宝。",
      ""
