    EventResult = {
      "3|光辉的夜明珠|答案应该不是这个，重新听一遍题目再思考一下吧。",
      "3|永恒的月亮|答案应该不是这个，重新听一遍题目再思考一下吧。",
      "3|璀璨的繁星|雅弗士兵说：“啊，不错，我想正确答案就是这样，您真不愧是‘神的喉舌’啊。”",
      ""
    },
    EventTitleText = "4|雅弗士兵|感谢您的解惑，且听我道来最后一个疑问吧。欧贝德还流传着一个古老的谜题，相信身为艾弥安的您一定听闻过此物，据说这是一种奇特的无价之宝，连雄才大略的大利乌大帝也不曾获取它们，我只知晓夜晚时，没人来接它们也会出现；白昼时，没人偷走它们却遍寻不着。",
