    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|让零来处理|这种时候还是零最靠谱。",
      "3|看向伊蕾什安|伊蕾什安或许能另辟蹊径……？",
      "",
      ""
    },
    EventResult = {
      "3|让零来处理|零说：“我注意到了，我会尝试将平台里的异物取出。”她试探了许久才将机关修好，并把卡在里面的东西完整交付与我。",
      "3|看向伊蕾什安|伊蕾什安说：“用最简单也最快速的方法吧。”我有一种不祥的预感，果不其然，下一秒钟伊蕾什安用镰刀暴力劈砍了机关一番，竟真的使其恢复了正常。",
      "",
      ""
    },
    EventTitleText = "4|平台|启动机关后并没有如想象中那样顺利运行，而是微微升起后便卡在了半空中，缝隙里似乎藏着什么东西。",
