    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|小心翼翼打开箱子|说不定里面藏着某种危险。",
      "3|用力砸开箱子|现在没时间慢吞吞开锁了。",
      "3|转身走开|乾的智者有言：事出反常必有妖。",
      ""
    },
    EventResult = {
      "3|小心翼翼打开箱子|……东西都被泡烂了，看看还有什么勉强用得上的。",
      "3|用力砸开箱子|零发出的动静太大，周围的动物渐渐向她聚来……她手执杖剑，做好了战斗准备。",
      "3|转身走开|安啾难以置信地扑腾了起来：直接走吗？真的可以吗？怎么会有人忍心不去开一只可疑的箱子啊！",
      ""
    },
    EventTitleText = "4|诡异的医疗箱|草丛中的医疗箱在月色下泛着诡异的光辉……等等，这种地方为什么会有医疗箱？而且仔细观察，似乎有青色的水正从里面渗出。",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 104051,
    InteractRange = 3,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 1,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "第四章交互宝箱-选错出虫子医疗箱",
