      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|先移动箱子|快刀斩乱麻吧。",
      "3|先整理箱子内部|箱子里的东西快溢出来了……",
      "",
      ""
    },
    EventResult = {
      "3|先移动箱子|零直接端起了一只箱子，不料那箱子早就漏了底，里面的东西“劈里啪啦”砸了一地。巨大的响声引来了数只虫子，看来它们蛰伏在这附近许久了。",
      "3|先整理箱子内部|我们花费了一点时间先整理好箱子内部，后续搬运的时候十分顺利，居民楼门口恢复了干净整洁。这时门里传出了一点动静，似乎有人来到了门口。",
      "",
      ""
    },
    EventTitleText = "4|居民楼门口|居民楼门口堆放着大量杂物，几乎没有过人的空间，把门堵住了，安全隐患可想而知。我们决定清理一下这些物品，可许多箱子已经倾倒，里面的东西随时有可能坠落在地上，该从哪里开始好呢？",
    HaveDialogue = 0,
