  [104111] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "对话",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|清理结晶|保护环境，人人有责。",
      "3|观察周围|什么东西在发光？",
      "",
      ""
    },
    EventResult = {
      "3|清理结晶|零听从我的指令，用手杖敲碎了灯柱上的青晶，发出的声响引来了不知从哪儿冒出的蚊群。",
      "3|观察周围|我环顾四周，终于找到了那个莫名引起我注意的东西——一只崭新的带锁箱子。也许里面还有有用的东西，试着打开看看吧。",
      "",
      ""
    },
    EventTitleText = "4|喷灌灯|草地里的喷灌灯被青色结晶包围，正发出“滋滋”的声音，吸引了我的注意。仔细一看，草丛里好像有东西……",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 104111,
    InteractRange = 3,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 1,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "第四章交互宝箱-水晶覆盖喷灌灯",
    PlayInteractSoundName = "",
    ServerEventPath = "box.104111",
    Shadow = 0,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
  [104131] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "对话",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|揭开铁皮|看看里面有什么……？",
      "3|扶正电线杆|要是倒下来就不得了了。",
      "3|检查配电箱|灯不亮肯定是电源的问题！",
      ""
    },
    EventResult = {
      "3|揭开铁皮|揭开铁皮后，迎接薪的竟是满满一袋青之水，劈头盖脸地浇在了她身上。",
      "3|扶正电线杆|电线杆恢复了垂直状态，至少不用担心它倒塌了。",
      "3|检查配电箱|配电箱仍和之前一样，内部贴着维修的示意图。",
      ""
    },
    EventTitleText = "4|电线杆|一根很眼熟的电线杆，它似乎又遭到了猛烈的撞击，一副随时都有可能倾倒的样子，导致周边一小片区域没有光源。电线杆旁边不知为何覆盖着一层铁皮，配电箱也不晓得还能否正常运行，薪想既然看见了那就不能置之不理吧！",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
