  [105051] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "对话",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    ChatHeight = 1.8,
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|打开箱子|里面不会是不小心被困住的小猫吧？",
      "3|询问工人|你好，请问……",
      "",
      ""
    },
    EventResult = {
      "3|打开箱子|箱子开启后，我被溅到了一身水，一大群蚊子紧跟其后朝我扑来……",
      "3|询问工人|我叫住了一位工人，向其询问箱子的异状，他解释说这是他们制作的用于诱捕蚊子的虫饵箱，能防止蚊子在作业期间骚扰他们。“这些蚊子似乎特别容易受到浩荡江水的吸引，只要你帮我往里面补充诱饵，我就送你一些回礼。”工人如是说道。",
      "",
