      "3|雅俗共赏|诶，我有个点子……",
      ""
    },
    EventResult = {
      "3|下里巴人|闪闪发光的特效，配上限时免费的罐头笑声，下方用黄底红字标出“惊爆价1.99元”的字样。虽称不上赏心悦目，但确实足够洗脑，天黎居民满意地送给我们一些谢礼。",
      "3|阳春白雪|启用全黑幕布和聚光灯，360°无死角展示商品，佐以高雅甚至有些不明觉厉的广告词，打造出奢侈品的气息。加上天黎氏的名气，或许可以打出品牌效应，天黎居民满意地送给我们一些谢礼。",
      "3|雅俗共赏|其实犯不上那么麻烦，你挑几个族里的俊男靓女往那儿一杵，肯定会有很多人涌入直播间。天黎居民听了茅塞顿开，满意地送给我们一些谢礼。",
      ""
    },
    EventTitleText = "4|天黎居民|这名天黎居民正准备把她的手工艺品挂到网上售卖，但苦于拍摄技术有限，听到这种事情阿紫怎能坐视不管。可问题在于，我们应该选择哪种宣传路线？",
