    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|落叶归根|那是苹果既定的宿命。",
      "3|苹果派|那是苹果最美味的变化。",
      "3|苹果并没有落下|是大地升空接住了苹果。",
      ""
    },
    EventResult = {
      "3|落叶归根|“您真是一位浑身充斥着浓郁文艺气息、情绪丰沛的人，苹果成熟后能够回归苹果树根，我们应当想象它是幸福的。正如苹果将会掉落，我与您的相遇，想必也是命运的安排。”",
      "3|苹果派|“您真是一位注重生活细节，实用至上的人，这样的回答竟然令此刻的我有些难过，因为我无法向您提供苹果派，我只能为您提供另一些补偿，并请允许我向您推荐德尔菲学院食堂二楼的厨师，想必他能在苹果派的喜好上与您产生共鸣。”",
      "3|苹果并没有落下|“令人惊叹的回答！不过新的问题产生了——我们先不谈苹果自身的状态是否会随着大地运动而产生变化——单单讨论大地升空一事，假使我的制作人将我摆在了天文学院的某个角落中，而天文学院与德尔菲分离，朝着太空飞去……那真是难以想象的场景……很难想象您经历过什么！”",
      ""
    },
    EventTitleText = "4|提问|当你看到苹果从树上落下时，你会联想到什么？",
