  [300908] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "操作",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "1|燃起火焰|开始炼金",
      "3|加入清水|开始炼金",
      "",
      ""
    },
    EventResult = {
      "1|燃起火焰|火焰燃烧，使得炼金器皿内的物质发生反应，产生的气体在铁管中冷凝成液体，顺着管道流入了最后一个器皿中。",
      "2|加入清水|炼金器皿内的物质开始产生剧烈反应，“砰”的一声，发生了爆炸。在科研的道路上，这样的爆炸并不少见，不幸中的万幸，此次你只是受了点皮外伤。",
      "",
      ""
    },
    EventTitleText = "4|古朴的炼金装置|桌上摆有两组炼金装置，桌上有一张写有孟斐斯文字的图纸，内容模糊不清，经过零的翻译，勉强能看出大意：<color=#D2982D>“火焰洗礼，迎来上升……泛滥之河，坠向灾祸……”</color>，这段文字的前后分别划了两个方向的箭头，指向了不同的炼金装置。",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 300908,
    InteractRange = 3,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 1,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "古朴的炼金装置",
    PlayInteractSoundName = "",
    ServerEventPath = "TONG.300908",
    Shadow = 0,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
