      "3|不速之客|刚拿起刀，便听到一声异响从盛放刀的底部圆盘传出，身后似乎来了一位不速之客……",
      "3|不作为|或许可以在周围找找，有没有关于如何分辨这真假朱辟的提示，或者可以直接观察刀身，也可直接拔刀试试……\n但如果什么都不做的话……目前看来，无事发生。",
      ""
    },
