  [10102102] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "操控",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "1|取下匕首|说不定可以修好台梯。",
      "4|离开|修好古代台梯可没那么简单。",
      "",
      ""
    },
    EventResult = {
      "1|年久失修|在一阵巨大的噪音后，升降台梯彻底停止了工作。你突然意识到，或许这把匕首本就是某种“修理”。……但至少，你得到了一把趁手的武器。|当前角色获得少量护盾值。",
      "4|另寻他路|升降梯的声响逐渐远去……",
      "",
      ""
    },
    EventTitleText = "4|故障的台梯|你靠向了升降台梯，石制的踏板虽然无法升起，但仍在原地颤动着，不停地发出奇怪的响动。顺着声响的源头看去，一把雅弗制式匕首正巧卡在了台梯滑板的位置……",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 10102102,
    InteractRange = 6,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 0,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "故障的台梯",
    PlayInteractSoundName = "",
    ServerEventPath = "MIN.10002",
    Shadow = 1,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
  [10102103] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "操控",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|废墟寻宝|把箱子从废墟中挖出来。",
      "4|放弃|智者不立于危墙。",
      "",
      ""
    },
    EventResult = {
      "2|无用至宝|打开箱子，你发现了一大堆由安息字母书写的纸张，根据零的翻译，这是安息帝国时期价值连城的地契。与此同时，挖掘废墟的声音吸引了一些不速之客……|出现一批新怪物。",
      "4|消除执念|集中精神，努力忘记宝箱的模样……",
      "",
      ""
    },
    EventTitleText = "4|断桥之后|越过崩毁的断桥，呈现在眼前并不是出口，而是另一处断壁残垣。颓败的废墟之下，显露出了华美箱匣的一角，里面似乎保存了什么重要的东西。",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 10102103,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 0,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "碍路的残骸-入口",
    PlayInteractSoundName = "",
    ServerEventPath = "MIN.10003",
    Shadow = 1,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
  [10102104] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "操控",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|承诺|我不会让它们被遗忘这里。",
      "4|无言|我们没有余力携带更多东西了。",
      "",
      ""
    },
    EventResult = {
      "1|被遗忘的知识|你带走了尽可能多的书卷，将它们放置在了安全的地方。在清点的时候，你意外地发现，其中夹杂着一张图书馆的手绘地图。|最大生命值得到了增加",
      "4|遗忘|扶去书卷上的泥尘，就此离去。",
      "",
      ""
    },
    EventTitleText = "4|最后的知识|在通道的末端，堆放着许多摆放整齐的书本与泥板。对比周遭的凌乱，这些有序的书卷反而显得格格不入，你仔细观察，发现某块暗红泥板的下方，还夹杂着一张染血的纸条：“来访的艾弥安啊，我恳请您，将这些知识带走吧……不要让它们沦落为入侵者的战利品。”",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 10102104,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 0,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "碍路的残骸-中台",
    PlayInteractSoundName = "",
    ServerEventPath = "MIN.10004",
    Shadow = 1,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
  [10102105] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "操控",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|交给零|零打算从外环开始解开绳结。",
      "3|交给伊蕾|伊蕾主张采取一些“特殊手段”。",
      "3|亲自出手|解开绳结并不是一件难事。",
      ""
    },
    EventResult = {
      "4|归零|每当零解开最外层的绳扣，又会变出更多的次生绳环。最终，你们选择将绳结放回原位，把谜题留给下一位到访者。",
      "1|解谜|伊蕾什安拿起镰刀，将其劈成了两半。虽然绳结之中空无一物，但你感觉心情舒畅多了。|当前角色获得少量护盾值。",
      "2|循环|再给我一点时间，我肯定能把它解开！|最大生命值被削减了。",
      ""
    },
    EventTitleText = "4|古怪绳结|废墟的一角，遗落着一个精巧的绳结，粗糙的麻绳如同一条噬神的长蛇纠葛在一起，绳环相扣、难解难分。不知为何，只是看到它，内心就莫名有一股想要解绳的冲动。",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 10102105,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 0,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "石中卷",
    PlayInteractSoundName = "",
    ServerEventPath = "MIN.10005",
    Shadow = 1,
    ShowEndMsg = false,
    ShowType = 4,
    Type = 13
  },
  [10102106] = {
    Arg = {"10102101"},
    BodyRadius = 1,
    ButtonIcon = "zjm_img_20",
    ButtonText = "操控",
    ChatActionList = {"", ""},
    ChatContent = {"", ""},
    Effect = {
      "Fx_Investigate",
      "H101004"
    },
    EventOptions = {
      "3|畅饮|相信古人的智慧。",
      "4|不喝|伊蕾什安肯定在骗我。",
      "",
      ""
    },
    EventResult = {
      "1|古代清泉|用手舀起，一饮而尽。泉水清凉，只是稍带点苦涩，但也足以冲洗旅途带来的疲惫。在确认你一切正常后，伊蕾什安这才走向喷泉，享用起清水。显然，她把你当成了某种人形试毒剂。|角色生命值得到了回复。",
      "4|稍有口渴|舔了舔嘴唇，继续踏上旅途。",
      "",
      ""
    },
    EventTitleText = "4|甘泉|这里伫立着一眼人工喷泉，虽然看上去可以直接饮用，但其中漂浮的杂质又提醒着你，这是两千年前的粗糙造物。正当你犹豫之时，耳畔传来了伊蕾什安的声音：“放心喝吧，我已经帮你尝过了，泉水甘甜可口，绝对没有问题。”",
    HaveDialogue = 0,
    Icon = "bb_icon_dj",
    Id = 10102106,
    InteractRange = 4.5,
    IsForeverRemove = 0,
    IsPlayInteractAnima = 0,
    IsRemove = 1,
    ModelId = "H101004",
    ModelScale = 1,
    Name = "喷泉水",
    PlayInteractSoundName = "",
    ServerEventPath = "MIN.10006",
    Shadow = 1,
    ShowEndMsg = false,
    ShowType = 4,
